/// Returns the SVG bytes for a `ProviderIcon-<slug>` resource name.
#[must_use]
pub fn svg_data(for_resource_name: &str) -> Option<Vec<u8>> {
    SVG_BY_RESOURCE_NAME
        .iter()
        .find_map(|(k, v)| (*k == for_resource_name).then(|| v.as_bytes().to_vec()))
}
